L(s,[('u1','Configure hardware','ہارڈ ویئر کی ترتیب','هارډویر تنظیم کړي'),('u2','Set the system clock','سسٹم کلاک مقرر کرنا','د سیسټم ساعت وټاکي'),('u3','Enable or disable system components','سسٹم اجزاء کو فعال یا غیر فعال کرنا','د سیسټم اجزا فعال یا غیر فعال کړي'),('u4','Select bootable device sequence','بوٹ ہونے والے آلے کی ترتیب منتخب کرنا','د بوټ کېدونکې وسیلې ترتیب وټاکي'),('u5','Set password for system and user login','سسٹم اور صارف لاگ ان کے لیے پاس ورڈ مقرر کرنا','د سیسټم او کاروونکي د ننوتو لپاره پټنوم وټاکي')],'bios')
