L(s,[('p1','Serial Ports','سیریل پورٹس','سریال پورټونه'),('p2','Parallel Port','پیرالل پورٹ','موازي پورټ'),('p3','PS/2 Mouse Port','پی ایس / ۲ ماؤس پورٹ','PS/2 موږک پورټ'),('p4','PS/2 Keyboard Port','پی ایس / ۲ کی بورڈ پورٹ','PS/2 کیبورډ پورټ'),('p5','VGA Port','وی جی اے پورٹ','VGA پورټ'),('p6','USB (Universal Serial Bus)','یو ایس بی (یونیورسل سیریل بس)','USB (نړیوال سریال بس)'),('p7','Ethernet LAN Port','ایتھرنیٹ ایل اے این پورٹ','ایترنېټ LAN پورټ'),('p8','Audio Ports','آڈیو پورٹس','غږیز پورټونه')],'ports')
